function validate([n, edges]) {
  if (!Number.isInteger(n) || n < 3 || n > 100000) return 'n is an integer from 3 to 10^5.';
  if (!Array.isArray(edges) || edges.length !== n) return 'There must be exactly n edges.';
  const seen = new Set();
  const parent = Array.from({ length: n }, (_, i) => i);
  const find = x => { while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; };
  let parts = n;
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) return 'Each edge is a pair [node1, node2].';
    const [a, b] = edge;
    if (![a, b].every(v => Number.isInteger(v) && v >= 0 && v < n)) return 'Edge ends must be nodes from 0 to n - 1.';
    if (a === b) return 'An edge must join two different nodes.';
    const key = Math.min(a, b) * n + Math.max(a, b);
    if (seen.has(key)) return 'Two nodes may be joined by at most one edge.';
    seen.add(key);
    const ra = find(a), rb = find(b);
    if (ra !== rb) { parent[ra] = rb; parts--; }
  }
  // Connected with n nodes and n edges means exactly one cycle.
  if (parts !== 1) return 'The graph must be connected.';
  return null;
}

