function distanceToCycle(n, edges) {
  const graph = Array.from({ length: n }, () => []);
  const degree = new Array(n).fill(0);
  for (const [a, b] of edges) {
    graph[a].push(b);
    graph[b].push(a);
    degree[a]++;
    degree[b]++;
  }

  const queue = [];
  for (let node = 0; node < n; node++) {
    if (degree[node] === 1) {
      queue.push(node);
    }
  }
  const onCycle = new Array(n).fill(true);
  for (let head = 0; head < queue.length; head++) {
    const node = queue[head];
    onCycle[node] = false;
    for (const next of graph[node]) {
      degree[next]--;
      if (degree[next] === 1) {
        queue.push(next);
      }
    }
  }

  const answer = new Array(n).fill(-1);
  const frontier = [];
  for (let node = 0; node < n; node++) {
    if (onCycle[node]) {
      answer[node] = 0;
      frontier.push(node);
    }
  }
  for (let head = 0; head < frontier.length; head++) {
    const node = frontier[head];
    for (const next of graph[node]) {
      if (answer[next] === -1) {
        answer[next] = answer[node] + 1;
        frontier.push(next);
      }
    }
  }
  return answer;
}

