function distanceToCycle(n, edges) {
  // An edge lies on the cycle exactly when its ends stay connected without it.
  const connectedWithout = (skip, from, to) => {
    const seen = new Set([from]);
    const stack = [from];
    while (stack.length) {
      const u = stack.pop();
      if (u === to) return true;
      edges.forEach(([a, b], i) => {
        if (i === skip) return;
        const v = a === u ? b : b === u ? a : -1;
        if (v >= 0 && !seen.has(v)) { seen.add(v); stack.push(v); }
      });
    }
    return false;
  };
  const cycle = new Set();
  edges.forEach(([a, b], i) => { if (connectedWithout(i, a, b)) { cycle.add(a); cycle.add(b); } });
  const result = [];
  for (let start = 0; start < n; start++) {
    const dist = new Map([[start, 0]]);
    const order = [start];
    let found = -1;
    for (let i = 0; i < order.length && found < 0; i++) {
      const u = order[i];
      if (cycle.has(u)) { found = dist.get(u); break; }
      for (const [a, b] of edges) {
        const v = a === u ? b : b === u ? a : -1;
        if (v >= 0 && !dist.has(v)) { dist.set(v, dist.get(u) + 1); order.push(v); }
      }
    }
    result.push(found);
  }
  return result;
}

