function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 3 + Math.floor(rand() * 8);
  const shape = rand();
  // Cycle length: anything from 3 to n, sometimes very short or the whole graph.
  let c;
  if (shape < 0.2) c = 3;
  else if (shape < 0.3) c = n;
  else c = 3 + Math.floor(rand() * (n - 2));
  const labels = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [labels[i], labels[j]] = [labels[j], labels[i]];
  }
  const edges = [];
  for (let i = 0; i < c; i++) edges.push([labels[i], labels[(i + 1) % c]]);
  // Hang the remaining nodes as trees; a high chain chance makes long paths.
  const chain = rand() < 0.5 ? 0.9 : 0.2;
  for (let i = c; i < n; i++) {
    const parent = rand() < chain ? labels[i - 1] : labels[Math.floor(rand() * i)];
    edges.push([labels[i], parent]);
  }
  for (let i = edges.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [edges[i], edges[j]] = [edges[j], edges[i]];
  }
  for (const edge of edges) if (rand() < 0.5) edge.reverse();
  return [n, edges];
}
